import { createServer } from "node:net";
import { defineConfig, devices } from "playwright/test";
// archetypes/shared/playwright.ts
/** A port nobody listens on now, so that several apps (or test runs) can check at the same time. */
const freePort = () => new Promise((resolve, reject) => {
	const server = createServer();
	server.on("error", reject);
	server.listen(0, "127.0.0.1", () => {
		const address = server.address();
		server.close(() => resolve(typeof address === "object" && address !== null ? address.port : 4317));
	});
});
const PORT = process.env["LERNAPPS_PREVIEW_PORT"] ??= String(await freePort());
const URL = `http://127.0.0.1:${PORT}/`;
const base = {
	testDir: "e2e",
	testMatch: "*.e2e.ts",
	forbidOnly: true,
	fullyParallel: true,
	workers: Number(process.env["LERNAPPS_PLAYWRIGHT_WORKERS"]) || "75%",
	retries: process.env["CI"] ? 2 : 0,
	reporter: [["line"]],
	use: {
		baseURL: URL,
		...process.env["LERNAPPS_CHROMIUM"] ? { launchOptions: { executablePath: process.env["LERNAPPS_CHROMIUM"] } } : {}
	},
	projects: [{
		name: "desktop",
		use: { ...devices["Desktop Chrome"] }
	}, {
		name: "360px",
		use: {
			...devices["Desktop Chrome"],
			viewport: {
				width: 360,
				height: 740
			}
		}
	}],
	webServer: {
		command: `vp preview --host 127.0.0.1 --port ${PORT} --strictPort`,
		url: URL
	}
};
/** The configuration, with the app's own settings over it. */
const playwright = (config = {}) => defineConfig(base, config);
var playwright_default = playwright();
export { playwright_default as default, playwright };
